{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C20"],
      "claim": "Clonidine, the closest structural analogue sharing the 2-aminoimidazoline/halogenated aromatic core, has an absolute oral bioavailability of 55.4% in children when compared with intravenous dosing, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "Alinidine, a clonidine-like 2-aminoimidazoline derivative, has an absolute oral bioavailability of 94% in humans, directly supporting high oral bioavailability for this structural class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Cibenzoline, an imidazoline-containing drug, shows 80–90% absolute oral bioavailability in healthy subjects, supporting high F for imidazoline-containing analogues.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C47"],
      "claim": "Midaglizole, another imidazoline-containing compound, has systemic bioavailability of at least 75% in humans after oral administration, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C41"],
      "claim": "Penclomedine, despite lower structural similarity, has a median absolute oral bioavailability of 73% (range 28–98%) in patients, providing additional supportive evidence for high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a clonidine-like 2-aminoimidazoline. The closest analogue clonidine has absolute oral bioavailability around 55% in children and higher in adults, while other imidazoline-containing analogues such as alinidine, cibenzoline, and midaglizole show 75–100% oral bioavailability. These direct human absolute-F measurements strongly support F ≥ 20%; no affirmative threshold-relevant evidence indicates low bioavailability.",
  "evidence_gaps": [
    "No direct pharmacokinetic measurement exists for the exact query molecule.",
    "Some supporting records are from children or patient populations rather than healthy adults.",
    "The pyronaridine low-bioavailability record is vague and structurally distant, so it was not treated as affirmative evidence for low F."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

